typedef void (*OnWalletChainLockProcessedCallback)(const char *wallet_id,
                                                   uint32_t cl_height,
                                                   const uint8_t (*cl_hash)[32],
                                                   const uint8_t (*cl_signature)[96],
                                                   const struct FFIChainlockedTxid *finalized,
                                                   uint32_t finalized_count,
                                                   void *user_data);

/**
 * Callback for `WalletEvent::ChainTruncated`.
 *
 * Fires once per wallet that processed a block above `height` when a fork
 * replaced the chain above it, and the wallet dropped what it recorded from
 * those blocks. A consumer mirroring wallet state to disk must delete the
 * `txids_count` transactions at `txids` with any UTXO they created, move the
 * `unconfirmed_txids_count` InstantSend-locked transactions at
 * `unconfirmed_txids` back to the mempool with their UTXOs, mark the
 * `restored_outpoints_count` coins at `restored_outpoints` unspent, and lower
 * its synced height to `height` when it is above it. `txids`,
 * `unconfirmed_txids` and `restored_outpoints` are null when their count is 0.
 *
 * All pointer parameters are borrowed and only valid for the duration of the
 * callback. `balance` is the wallet's balance *after* the truncation;
 * `account_balances` follows the same contract as on
 * [`OnTransactionDetectedCallback`].
 */
typedef void (*OnChainTruncatedCallback)(const char *wallet_id,
                                         uint32_t height,
                                         const uint8_t (*txids)[32],
                                         uintptr_t txids_count,
                                         const uint8_t (*unconfirmed_txids)[32],
                                         uintptr_t unconfirmed_txids_count,
                                         const struct FFIOutPoint *restored_outpoints,
                                         uintptr_t restored_outpoints_count,
                                         const FFIBalance *balance,
                                         const struct FFIAccountBalance *account_balances,
                                         uint32_t account_balances_count,
                                         void *user_data);

/**
 * Wallet event callbacks - one callback per WalletEvent variant.
 *
 * Set only the callbacks you're interested in; unset callbacks will be ignored.
 *
 * All pointer parameters passed to callbacks (wallet IDs, txids, records,
 * balances) are borrowed and only valid for the duration of the callback
 * invocation. Callers must copy any data they need to retain.
 */
typedef struct FFIWalletEventCallbacks {
  OnTransactionDetectedCallback on_transaction_detected;
  OnTransactionInstantLockedCallback on_transaction_instant_locked;
  OnTransactionsSweptCallback on_transactions_swept;
  OnWalletBlockProcessedCallback on_block_processed;
  OnSyncHeightAdvancedCallback on_sync_height_advanced;
  OnWalletChainLockProcessedCallback on_chain_lock_processed;
  OnChainTruncatedCallback on_chain_truncated;
  void *user_data;
} FFIWalletEventCallbacks;

/**
 * Callback for fatal client errors (e.g. start failure, monitor thread crash).
 *
 * The `error` string pointer is borrowed and only valid for the duration
 * of the callback. Callers must copy the string if they need to retain it
 * after the callback returns.
 */
typedef void (*OnClientErrorCallback)(const char *error, void *user_data);

/**
 * Client error callback configuration.
 */
typedef struct FFIClientErrorCallback {
  OnClientErrorCallback on_error;
  void *user_data;
} FFIClientErrorCallback;

/**
 * All event callbacks grouped into a single struct.
 *
 * Pass this to `dash_spv_ffi_client_new`. Any callback group left at its
 * default (all function pointers null) will simply not receive events.
 */
typedef struct FFIEventCallbacks {
  struct FFISyncEventCallbacks sync;
  struct FFINetworkEventCallbacks network;
  struct FFIProgressCallback progress;
  struct FFIWalletEventCallbacks wallet;
  struct FFIClientErrorCallback error;
} FFIEventCallbacks;

/**
 * Network-level outcome of a broadcast, as returned by
 * `dash_spv_ffi_client_broadcast_transaction_and_wait`.
 *
 * Plain value type — nothing to free.
 */
typedef struct FFIBroadcastResult {
  /**
   * The determined outcome.
   */
  enum FFIBroadcastStatus status;
  /**
   * Distinct non-recipient peers that announced the txid back
   * (meaningful for `Accepted`).
   */
  uint32_t relayed_by;
} FFIBroadcastResult;

/**
 * Opaque handle to the wallet manager owned by the SPV client.
 *
 * This is intentionally zero-sized so it can be used purely as an FFI handle
 * while still allowing Rust to cast to the underlying key-wallet manager
 * implementation when necessary.
 */
typedef struct FFIWalletManager {
  uint8_t _private[0];
} FFIWalletManager;

/**
 * FFIResult type for error handling
 */
typedef struct FFIResult {
  int32_t error_code;
  /**
   * The calling thread's last error (see `dash_spv_ffi_get_last_error`), or
   * null on success. It can also be null with a non-zero `error_code`: a
   * failure during thread teardown has no message. Never force-unwrap it
   * (in Swift, treat nil as "no message available"). Owned by the library
   * and valid only on the calling thread, until that thread makes another
   * call that sets or clears its error, or exits; copy it before passing it
   * to another thread.
   */
  const char *error_message;
} FFIResult;

